    "content": "最近在做技术制图和自动化工作流时，整理了一个开源项目： CADCraft 。 它是一款免费、开源的 2D CAD 应用，使用 Rust 构建，支持 Windows 、macOS 、Linux 、FreeBSD 和 WebAssembly 。除了 LINE 、CIRCLE 、ARC 、OFFSET 、TRIM 、HATCH 、DIM 等常见绘图工具，还支持图层、尺寸、DWG/DXF 工作流，以及 PDF 、SVG 、PNG 导出。 比较特别的是它提供 MCP 、JSON 控制和无头 CLI ，可以让脚本或 AI ag…"
