    "content": "rg （ ripgrep ）是一个很强大的工具，但并不是每个平台都有。 有时候我想在 Python 或其他语言里使用它，但平台、CPU 架构和编程语言的组合实在太多了，处理起来比较麻烦。 所以我把它做成了 APE （ Actually Portable Executable ），这样只需要一个可执行文件，就能在 Windows 、Linux 和 macOS 上运行，同时支持 x86_64 和 ARM64 架构。 然后利用 APEBind ，为不同编程语言生成统一的调用接口。这样无论使用哪种语言，想调用 rg 都会方…"
