    "content": "中国六省人事大调整，云南和湖南党政主官双双换人，中共中央宣传部副部长、国务院新闻办公室主任 莫高义 ，以及国务院副秘书长 王志军 ，分别“空降”云南和湖南出任省委书记。上述两省以及青海、福建、河北、江西也都迎来新的省政府“一把手”。 这轮人事调动后，莫高义成为目前唯一的“双非”（非中共中央委员、非中央候补委员）省委书记，西南三省当前已全部由宣传系统背景的官员主政；出任福建省政府“一把手”的 郭宁宁 ，将成为中国首位“70后”女省长；而曾被视为“70后”政坛新星的 诸葛宇杰 履新青海省政府党组书记，在副部级九年后晋升…"
