    "description": "新华社天津10月24日电（记者张建新、栗雅婷）秋末冬初，气温变化较大，老年人血管调节、呼吸道防御能力下降，是秋冬老年急症多发、住院增多的原因之一。如何做好老年人秋冬健康防护？ 天津医科大学总医院老年病科（保健医疗部）主任医师张伟三提醒，在日常生活中，有的老年人外观状态平稳，自述无明显不适，家属也认为一切正常，可一旦发病，往往已经发展为重症、急症。针对老年疾病沉默起病、隐匿进展的突出特点，建议家属要经常对照老人既往常态观察变化，一旦察觉异…",
    "content": "新华社天津10月24日电（记者张建新、栗雅婷）秋末冬初，气温变化较大，老年人血管调节、呼吸道防御能力下降，是秋冬老年急症多发、住院增多的原因之一。如何做好老年人秋冬健康防护？ 天津医科大学总医院老年病科（保健医疗部）主任医师张伟三提醒，在日常生活中，有的老年人外观状态平稳，自述无明显不适，家属也认为一切正常，可一旦发病，往往已经发展为重症、急症。针对老年疾病沉默起病、隐匿进展的突出特点，建议家属要经常对照老人既往常态观察变化，一旦察觉异常，要摒弃“再等等看”的侥幸心理，及时就诊评估。 张伟三表示，随着年龄增长，人体…"
