    "description": "新华社拉萨10月24日电（记者李键、刘洪明）记者从中国铁路青藏集团有限公司获悉，青藏铁路格拉段临时限速措施23日夜间全部取消，经全面排查，线路设备无异常，列车恢复正常速度运行，运输秩序平稳有序。 西藏巴青7.0级地震发生后，格尔木至拉萨部分区段铁路线路、设备受到震情波及。青藏集团公司对受地震影响区段实施临时管控，精准扣停在途列车，封锁相关线路，并统筹调度各专业人员全面开展设备隐患排查、行车秩序管控等各项工作。 为精准识别铁路沿线风险和隐…",
    "content": "新华社拉萨10月24日电（记者李键、刘洪明）记者从中国铁路青藏集团有限公司获悉，青藏铁路格拉段临时限速措施23日夜间全部取消，经全面排查，线路设备无异常，列车恢复正常速度运行，运输秩序平稳有序。 西藏巴青7.0级地震发生后，格尔木至拉萨部分区段铁路线路、设备受到震情波及。青藏集团公司对受地震影响区段实施临时管控，精准扣停在途列车，封锁相关线路，并统筹调度各专业人员全面开展设备隐患排查、行车秩序管控等各项工作。 为精准识别铁路沿线风险和隐患，青藏集团公司对受地震影响区段的钢轨线路、路基边坡、桥梁隧道、涵洞支座等关键设…"
