    "author": "",
    "description": "新华社香港10月24日电（谢妞）炫酷的航天模型、悬浮飞驰的磁浮列车模型、魔幻的“点水成冰”实验……24日，由香港特区政府创新科技署主办的“创新科技嘉年华2026”在香港科学园正式拉开帷幕。为期9天的年度创科盛会，以“创科领航 梦想高飞”为主题，为全港市民打造一场精彩纷呈、互动感十足的科技盛宴。 活动现场，香港特区政府财政司司长陈茂波表示，特区政府上月公布的香港第一个五年规划正为创科发展创造更有力的制度支撑。规划以北部都会区为创科产业发展…",
    "content": "新华社香港10月24日电（谢妞）炫酷的航天模型、悬浮飞驰的磁浮列车模型、魔幻的“点水成冰”实验……24日，由香港特区政府创新科技署主办的“创新科技嘉年华2026”在香港科学园正式拉开帷幕。为期9天的年度创科盛会，以“创科领航 梦想高飞”为主题，为全港市民打造一场精彩纷呈、互动感十足的科技盛宴。 活动现场，香港特区政府财政司司长陈茂波表示，特区政府上月公布的香港第一个五年规划正为创科发展创造更有力的制度支撑。规划以北部都会区为创科产业发展的载体，推动教育、科技、人才、产业一体化发展，让大学育才、科研创新和产业需求紧密…"
