    "description": "10月24日16时39分，青海玉树州杂多县发生5.3级地震，记者在杂多县县城表示未感受到明显震感。 与西藏巴青县交界处的杂多县查旦乡有震感，目前暂未收到新的人员受伤和房屋受损报告。 记者：李占轶、柳泽兴 新华社音视频部制作",
