    "description": "新华社日本名古屋10月24日电（记者岳晨星、郑直）24日，第五届亚洲残疾人运动会在日本名古屋瑞穗公园田径场闭幕。中国体育代表团获得207枚金牌、117枚银牌和111枚铜牌，共435枚奖牌，连续第五届位居金牌榜、奖牌榜首位，创造境外参加亚残运会最好成绩。 本届赛事，中国代表团派出312名运动员参加17个大项的比赛，是参加境外亚残运会运动员规模最大的一届，共打破11项世界纪录、18项亚洲纪录。男子轮椅击剑运动员仲赛春担任闭幕式中国代表团旗手…",
