    "content": "问题现象 在 Arch Linux 上使用 Apostrophe Markdown 编辑器时，如果你没有开启系统代理，预览区内的 LaTeX 数学公式（如 $$...$$ ）就无法正常显示。 但只要 开启代理（科学上网），公式就能立刻渲染 。 根本原因 Apostrophe 在生成预览时，底层调用了 pandoc 进行转换。在它的源码 preview_converter.py 中，硬编码了参数 '--math-method=mathjax' 。 这个参数会导致 Pandoc 在生成的 HTML 里插入一段指向外部 …"
