    "description": "家里宽带用的中兴 F4600T 的 SDN 光猫，因为有 2 台 IPTV 的缘故，所以用的光猫拨号，然后路由器折腾了半天一直拿不到 V6 地址，后来索性海鲜市场淘了个 F7005TV3 ，换上之后还是一样没有 V6 也试了光猫改桥接，路由器拨号，华硕固件设置的 IPV6 Native ，也没用，到底是什么原因？真的快折腾疯了",
    "content": "家里宽带用的中兴 F4600T 的 SDN 光猫，因为有 2 台 IPTV 的缘故，所以用的光猫拨号，然后路由器折腾了半天一直拿不到 V6 地址，后来索性海鲜市场淘了个 F7005TV3 ，换上之后还是一样没有 V6 也试了光猫改桥接，路由器拨号，华硕固件设置的 IPV6 Native ，也没用，到底是什么原因？真的快折腾疯了"
