    "description": "这是10月24日在广东省深圳市拍摄的“一国两制”学术研讨会。新华社记者 王丰 摄 新华社深圳10月24日电（记者王丰）24日，由中国社会科学院主办的“一国两制”学术研讨会在深圳召开，本次研讨会以“港澳五年规划与融入服务国家发展大局”为主题，围绕“港澳五年规划与核心竞争力提升”“粤港澳大湾区建设与港澳融入国家发展大局”“发挥港澳独特优势服务国家高水平对外开放”等议题展开深入研讨，来自内地、香港、澳门以及海外的近100位嘉宾、专家学者参加会…",
    "content": "这是10月24日在广东省深圳市拍摄的“一国两制”学术研讨会。新华社记者 王丰 摄 新华社深圳10月24日电（记者王丰）24日，由中国社会科学院主办的“一国两制”学术研讨会在深圳召开，本次研讨会以“港澳五年规划与融入服务国家发展大局”为主题，围绕“港澳五年规划与核心竞争力提升”“粤港澳大湾区建设与港澳融入国家发展大局”“发挥港澳独特优势服务国家高水平对外开放”等议题展开深入研讨，来自内地、香港、澳门以及海外的近100位嘉宾、专家学者参加会议。 与会者对香港特区编制实施首个五年规划、澳门特区发布实施新一个五年规划的理论…"
