    "author": "",
    "description": "新华社达喀尔10月24日电（记者陈晨）2026年塞内加尔中国电影节23日在首都达喀尔开幕，约100名两国各界嘉宾出席开幕式，并观看开场电影《捕风追影》。 中国驻塞内加尔大使李志刚在致辞中表示，今年是中国和非洲开启外交关系70周年，也是“中非人文交流年”。电影是跨越国界、沟通心灵的桥梁，希望通过电影这扇窗口，让塞内加尔观众更直观地感受中国的历史底蕴、时代风貌和社会生活。 塞内加尔文化、手工业和旅游部官员哈吉·塔诺尔·宁说，本次电影节为塞内…",
