    "content": "10月24日，记者来到位于西藏那曲市巴青县玛如乡格隆改村的震后安置点，现场可以看到，救援帐篷陆续搭建完毕，物资补给点、热食供应点同步投用，受灾群众基本生活得到保障。 记者：李姝莛、李亚光、李恒毅、洪靓 新华社音视频部制作"
