    "description": "新华社天津10月24日电 题：天津制造“深蓝分量”更足 新华社记者郭方达、杨文、梁姊 清晨，渤海湾的海风掠过海油工程天津智能制造基地。码头上，万吨级运输船静静靠泊，刚完成总装的千吨级导管架和平台组块矗立岸边，等待吊装启运。这批海工装备将从这里出发，驶向渤海深处的油气田。 海洋装备，是天津制造的一块“压舱石”。前三季度，全市装备制造业增加值同比增长9.2%，其中海洋装备领域增长37.2%；海工装备产业链95家入链企业实现产值238.2亿元…",
