    "description": "10月24日，金星运行至地球与太阳之间，迎来下合日。天文科普专家表示，金星下合日，意味着金星从傍晚天空逐步转入清晨天空。从11月初开始，金星将以启明星的身份出现在黎明前的东方低空。 这是2025年7月9日在青海省海晏县拍摄的启明星。（钟奕 摄） 即使不在亮度峰值，金星也是天幕上格外醒目的天体，多数时段亮度可达-4等左右。由于金星比地球更接近太阳，我们通常只能在日出之前、日落之后的天空见到它。金星日出之前现身，被叫作“启明”；日落之后出现…",
    "content": "10月24日，金星运行至地球与太阳之间，迎来下合日。天文科普专家表示，金星下合日，意味着金星从傍晚天空逐步转入清晨天空。从11月初开始，金星将以启明星的身份出现在黎明前的东方低空。 这是2025年7月9日在青海省海晏县拍摄的启明星。（钟奕 摄） 即使不在亮度峰值，金星也是天幕上格外醒目的天体，多数时段亮度可达-4等左右。由于金星比地球更接近太阳，我们通常只能在日出之前、日落之后的天空见到它。金星日出之前现身，被叫作“启明”；日落之后出现，则被称为“长庚”。 这是2026年9月14日在天津市东丽区拍摄的长庚星伴月。（…"
